" stroke=\"#38bdf8\" stroke-width=\"1.5\" stroke-dasharray=\"5,5\"/></g>\n                  <g class=\"el\" data-beat=\"7\"><text x=\"275\" y=\"140\" fill=\"#94a3b8\" font-size=\"14\" text-anchor=\"middle\">d² = 22² + 3²</text></g>\n                  <g class=\"el\" data-beat=\"8\"><text x=\"275\" y=\"168\" fill=\"#38bdf8\" font-size=\"14\" text-anchor=\"middle\">d² = 484 + 9 = 493</text></g>\n                  <g class=\"el\" data-beat=\"9\"><rect x=\"170\" y=\"195\" width=\"210\" height=\"42\" rx=\"10\" fill=\"rgba(52,211,153,0.15)\" stroke=\"#34d399\" stroke-width=\"2\"/><text x=\"275\" y=\"223\" fill=\"#34d399\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">d ≈ 22.2 yd</text></g>\n                  <g class=\"el\" data-beat=\"10\"><text x=\"275\" y=\"255\" fill=\"#fbbf24\" font-size=\"13\" text-anchor=\"middle\">Fielder's diagonal run ≈ 22.2 yards ✓</text></g>\n                </g>",
